  "13": {
    "id": 13,
    "Link_Prehab": "https://pro.theprehabguys.com/patient-portal/programs/WJBUL7HQ",
    "link_prehab": "https://pro.theprehabguys.com/patient-portal/programs/WJBUL7HQ",
    "name": "GIULIA CASERTA",
    "phases": {
      "F1": {
        "phase_num": "1",
        "title": "FASE INIZIALE — Rilascio, Ripristino del ROM e Attivazione di base",
        "objective": "Attivare la retrazione scapolare destra, sbloccare la spalla sinistra (abduzione), educare la stabilità lombare tramite IAP e allungare le catene rigide.",
        "exercises": [
          {
            "exercise": "SMR Combo (Pettorali/Dorsali Sx + Tibiale Post Dx)",
            "target": "Rilasciare gli intrarotatori spalla sx ed inversori piede dx.",
            "params": "1x2 min per zona [RPE: N/A, Tempo: Lento]",
            "notes": "Pallina da tennis su spalla sx e sul bordo interno tibia destra."
          },
          {
            "exercise": "Mobilizzazione Sottoastragalica (Dx) & IAP",
            "target": "Sbloccare la pronazione/eversione dx ed attivare IAP.",
            "params": "W1: 3x8, W2: 3x10 [RPE: 7, Tempo: 3-1-1-0]",
            "notes": "Rotazione interna ginocchio dx a terra per eversione + respirazione IAP."
          },
          {
            "exercise": "Retrazioni Scapolari (Dx) & Scapular Wall Slides (Sx)",
            "target": "Riequilibrare la mobilità scapolo-toracica bilaterale.",
            "params": "W1: 3x8, W2: 3x10 [RPE: 7, Tempo: 3-1-1-0]",
            "notes": "Retrazione a braccia tese dx + scorrimento al muro a sx."
          },
          {
            "exercise": "Cat-Cow Selettivo (Lombare) & Short Foot (Sx)",
            "target": "Mobilizzare la lombare ed attivare l'arco plantare sx.",
            "params": "W1: 3x12, W2: 3x15 [RPE: 7, Tempo: 3-2-1-0]",
            "notes": "Cat-cow lento lombare abbinato a short foot a terra a sinistra."
          },
          {
            "exercise": "Stretching Soleo e Polpaccio (Sx)",
            "target": "Mobilizzare caviglia sx per ridurre eversione in squat.",
            "params": "W1: 3x10, W2: 3x12 [RPE: 7, Tempo: 3-1-1-0]",
            "notes": "Stretching soleo sx con ginocchio flesso contro parete."
          }
        ]
      },
      "F2": {
        "phase_num": "2",
        "title": "FASE INTERMEDIA — Rinforzo segmentale e Stabilità statica/dinamica",
        "objective": "Rinforzare la stabilità lombo-pelvica nello squat, rinforzare i retrattori scapolari destri e stabilizzare il piede sinistro.",
        "exercises": [
          {
            "exercise": "YTWL Scapolari con elastico leggero (focus Dx)",
            "target": "Rinforzo e coordinazione dei pivot scapolari destri.",
            "params": "W3: 3x8, W4: 3x10, W5: 4x8 [RPE: 8, Tempo: 3-1-1-0]",
            "notes": "Mantenere spalla dx depressa durante le forme Y-T-W-L."
          },
          {
            "exercise": "Iso-Squat a 100° al muro con attivazione IAP",
            "target": "Consolidare la stabilità lombare prima del crollo oltre 110°.",
            "params": "W3: 3x30\", W4: 3x45\", W5: 3x60\" [RPE: 8, Tempo: Iso]",
            "notes": "Mantenere lombare neutra e core attivo contro il muro a 100°."
          },
          {
            "exercise": "Inversione Caviglia con elastico (SOLO SX)",
            "target": "Rinforzo tibiale posteriore sx. Dx continua mobilità.",
            "params": "W3: 3x10, W4: 3x12, W5: 4x10 [RPE: 8, Tempo: 3-1-1-0]",
            "notes": "Esegui inversione caviglia sx. A destra fare solo rilascio/mobilità."
          },
          {
            "exercise": "One Leg Stance (Sx) su tavoletta stabile",
            "target": "Sviluppare il controllo monopodalico attivo a sinistra.",
            "params": "W3: 3x30\", W4: 3x45\", W5: 3x60\" [RPE: 8, Tempo: Iso]",
            "notes": "Piede sx attivo (non crollare in eversione), ginocchio sx allineato."
          },
          {
            "exercise": "Side Plank (Bilaterale)",
            "target": "Rinforzo catena laterale e stabilità lombo-pelvica.",
            "params": "W3: 3x30\", W4: 3x45\", W5: 3x60\" [RPE: 8, Tempo: Iso]",
            "notes": "Mantenere l'allineamento laterale senza crollare con le anche."
          }
        ]
      },
      "F3": {
        "phase_num": "3",
        "title": "FASE AVANZATA — Controllo motorio complesso e Integrazione funzionale",
        "objective": "Ottimizzare lo squat completo controllando il bacino, stabilizzare il ginocchio destro in Step Over ed integrare il piede in spinta.",
        "exercises": [
          {
            "exercise": "Squat completo (sotto i 110°) controllato",
            "target": "Accosciata controllata oltre i 110° con lombare neutra.",
            "params": "W6: 3x6, W7: 3x8, W8: 4x6 [RPE: 8-9, Tempo: 3-1-1-0]",
            "notes": "Discesa controllata (4\" eccentrica) monitorando lo shift del bacino."
          },
          {
            "exercise": "Step Down laterale su box (focus Sx)",
            "target": "Controllo eccentrico arto sx per prevenire eversione in squat.",
            "params": "W6: 3x6, W7: 3x8, W8: 4x6 [RPE: 8-9, Tempo: 3-1-1-0]",
            "notes": "Su box da 15 cm. Discesa controllata col ginocchio sx allineato."
          },
          {
            "exercise": "Squat completo con Overhead Reach (bastone)",
            "target": "Estensione toraco-lombare e accosciata con presa larga.",
            "params": "W6: 3x6, W7: 3x8, W8: 4x6 [RPE: 8-9, Tempo: 3-1-1-0]",
            "notes": "Presa strappo sul bastone per ridurre flessione spalle e salvare la lombare."
          },
          {
            "exercise": "Landing Control Monopodalico (lato Dx e Sx)",
            "target": "Ammortizzazione e prevenzione specifica.",
            "params": "W6: 3x6, W7: 3x8, W8: 4x6 [RPE: 8-9, Tempo: 2-0-1-0 (Decel)]",
            "notes": "Salto da box da 20 cm, atterraggio monopodalico stabile per 2\". Focus su allineamento."
          },
          {
            "exercise": "Skip alto e arresto monopodalico su Sx",
            "target": "Trasferimento dinamico reattivo della stabilità podalica.",
            "params": "W6-W8: 3x15 metri [RPE: 8, Tempo: Dinamico]",
            "notes": "Skip veloci ed arresto monopodalico su piede sx in controllo."
          }
        ]
      }
    }
  }
